use verus::prelude::*;

#[verifier(require)]
// no pre‐condition needed in this simple case

#[verifier(ensure)]
// The length of the result is exactly one more than the length of `a`.
#[verifier(ensures(result@.len() == a@.len() + 1))]

// All the old elements of `a` are still in place at the front of `result`.
#[verifier(ensures(
    forall(|i: usize| i < a@.len() ==> result@[i] == a@[i])
))]

// The newly appended element `b` sits at the very end.
#[verifier(ensures(result@[a@.len()] == b))]
fn append(a: &Vec<i32>, b: i32) -> Vec<i32> {
    // Pre-allocate a new Vec with enough capacity for all elements plus one more.
    let mut result = Vec::with_capacity(a.len() + 1);
    // Copy all elements from `a` into `result`.
    result.extend_from_slice(a);
    // Append the new element.
    result.push(b);
    result
}

